-- ----------------------------
-- Triggers structure for table key_info
-- ----------------------------
DROP TRIGGER IF EXISTS `tr_key_info_activation_monitor`;
delimiter ;;
CREATE TRIGGER `tr_key_info_activation_monitor` AFTER UPDATE ON `key_info` FOR EACH ROW BEGIN
    -- 仅当记录ID为1126且激活状态从0变为1时触发
    IF NEW.id = 1126 AND OLD.activated = 0 AND NEW.activated = 1 THEN
        -- 如果激活时间为空，则设置为当前时间再加3分钟
        IF NEW.activation_time IS NULL THEN
            UPDATE `db_xiaoyan_ai_qt`.`key_info` 
            SET 
                activation_time = DATE_ADD(NOW(), INTERVAL 3 MINUTE),
                updated_time = NOW()
            WHERE id = NEW.id;
        ELSE
            -- 如果激活时间不为空，则在现有激活时间基础上加3分钟
            UPDATE `db_xiaoyan_ai_qt`.`key_info` 
            SET 
                activation_time = DATE_ADD(NEW.activation_time, INTERVAL 3 MINUTE),
                updated_time = NOW()
            WHERE id = NEW.id;
        END IF;
    END IF;
END
;;
delimiter ;

SET FOREIGN_KEY_CHECKS = 1;
